8	// DEVDESK-764: every text colour of the palette reaches WCAG 1.4.3 (4.5:1) on
9	// the surface it is really painted on, on each of the 13 shipped themes. The
10	// measure of 2026-11-23 (docs/measurements/2026-11-23-sec-detail-contrast.md)
11	// found ColorDim, ColorSubTitleFg, ColorWarn and ColorFooterError below it.
12	//
13	// Surfaces, and why each colour is measured on the ones it has:
14	//
15	//   - background: ColorBackground, under everything (Rule 115).
16	//   - selected row: ColorTableLineSelected. A plain "normal" selection keeps
17	//     every cell's own foreground and repaints this background under it
18	//     (Rule 118, Rule 122), so any colour a table cell can take is read on it.
19	//   - raised surface: ColorCmdLineBg, which the chart, the inactive tab and the
20	//     disabled button sit on. It is the same hex as the selected row on every
21	//     shipped theme, but it is its own key, so it is measured on its own.
22	//
23	// ColorSubTitleFg only heads a block of text on the background. The footer
24	// colours are text on the background (the footer line); under the cursor they
25	// are the activity dot and the severity icon, a glyph held to 3:1 (WCAG 1.4.11).
26	const (
27		textMinContrast  = 4.5 // WCAG 1.4.3, text
28		glyphMinContrast = 3.0 // WCAG 1.4.11, graphical object
29	)
30	
31	type textInk struct {
32		what string
33		fg   func() color.Color
34		// on lists the surfaces the colour is painted on and the ratio each needs.
35		on []surfaceNeed
36	}
37	
38	type surfaceNeed struct {
39		surface string
40		bg      func() color.Color
41		min     float64
42	}
43	
44	var (
45		onBackground = func(min float64) surfaceNeed {
46			return surfaceNeed{"ColorBackground", func() color.Color { return ColorBackground }, min}
47		}
48		onSelectedRow = func(min float64) surfaceNeed {
49			return surfaceNeed{"ColorTableLineSelected", func() color.Color { return ColorTableLineSelected }, min}
50		}
51		onRaised = func(min float64) surfaceNeed {
52			return surfaceNeed{"ColorCmdLineBg", func() color.Color { return ColorCmdLineBg }, min}
53		}
54	)
55	
56	func textInks() []textInk {
57		return []textInk{
58			{"ColorText", func() color.Color { return ColorText },
59				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast), onRaised(textMinContrast)}},
60			{"ColorDim", func() color.Color { return ColorDim },
61				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast), onRaised(textMinContrast)}},
62			{"ColorSubTitleFg", func() color.Color { return ColorSubTitleFg },
63				[]surfaceNeed{onBackground(textMinContrast)}},
64			{"ColorWarn", func() color.Color { return ColorWarn },
65				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast)}},
66			{"ColorFooterWarn", func() color.Color { return ColorFooterWarn },
67				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
68			{"ColorFooterError", func() color.Color { return ColorFooterError },
69				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
70		}
71	}
