import json,glob,math
def lab(h):
    h=h.lstrip('#'); 
    if len(h)==3: h=''.join(c*2 for c in h)
    rgb=[int(h[i:i+2],16)/255 for i in (0,2,4)]
    lin=[c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4 for c in rgb]
    X=(0.4124564*lin[0]+0.3575761*lin[1]+0.1804375*lin[2])/0.95047
    Y=(0.2126729*lin[0]+0.7151522*lin[1]+0.0721750*lin[2])
    Z=(0.0193339*lin[0]+0.1191920*lin[1]+0.9503041*lin[2])/1.08883
    f=lambda t: t**(1/3) if t>0.008856 else 7.787*t+16/116
    fx,fy,fz=f(X),f(Y),f(Z)
    return (116*fy-16,500*(fx-fy),200*(fy-fz))
def d(a,b): return math.dist(lab(a),lab(b))
for f in sorted(glob.glob('themes/*.json')):
    t=json.load(open(f)); n=f.split('/')[-1][:-5]
    toks={k:t[k] for k in ['token_input','token_output','token_cache_write','token_cache_read']}
    print(n, 'border:',{k[6:]:round(d(v,t['viewport_border']),1) for k,v in toks.items()}, 'dim:',{k[6:]:round(d(v,t['color_dim']),1) for k,v in toks.items()}, 'high:',{k[6:]:round(d(v,t['severity_high']),1) for k,v in toks.items()})
EOF

